create extension if not exists pgcrypto;
create table if not exists users(user_id uuid primary key default gen_random_uuid(),name varchar(120) not null,username varchar(60) unique not null,email varchar(255) unique not null,password_hash text not null,profile_picture text,bio text default '',interests text default '',role varchar(20) default 'user',created_at timestamptz default now());
create table if not exists skills(skill_id uuid primary key default gen_random_uuid(),user_id uuid references users(user_id) on delete cascade not null,skill_name varchar(100) not null,category varchar(60) not null,current_level varchar(20) default 'BEGINNER',target_level varchar(20) default 'INTERMEDIATE',start_date date,target_date date,status varchar(20) default 'ACTIVE',description text default '',created_at timestamptz default now());
create table if not exists goals(goal_id uuid primary key default gen_random_uuid(),skill_id uuid references skills(skill_id) on delete cascade not null,user_id uuid references users(user_id) on delete cascade not null,title varchar(160) not null,target_value numeric(12,2) not null,current_value numeric(12,2) default 0,unit varchar(30) default 'hours',deadline date,status varchar(20) default 'ACTIVE',created_at timestamptz default now());
create table if not exists milestones(milestone_id uuid primary key default gen_random_uuid(),goal_id uuid references goals(goal_id) on delete cascade not null,title varchar(160) not null,target_value numeric(12,2) not null,achieved boolean default false,achieved_at timestamptz,created_at timestamptz default now());
create table if not exists practice_sessions(session_id uuid primary key default gen_random_uuid(),user_id uuid references users(user_id) on delete cascade not null,skill_id uuid references skills(skill_id) on delete cascade not null,duration_minutes integer not null,activity varchar(200) not null,notes text default '',practiced_at timestamptz default now());
create table if not exists posts(post_id uuid primary key default gen_random_uuid(),user_id uuid references users(user_id) on delete cascade not null,skill_id uuid references skills(skill_id) on delete set null,content varchar(2000) not null,media_url text,created_at timestamptz default now());
create table if not exists comments(comment_id uuid primary key default gen_random_uuid(),post_id uuid references posts(post_id) on delete cascade not null,user_id uuid references users(user_id) on delete cascade not null,content varchar(1000) not null,created_at timestamptz default now());
create table if not exists likes(like_id uuid primary key default gen_random_uuid(),post_id uuid references posts(post_id) on delete cascade not null,user_id uuid references users(user_id) on delete cascade not null,created_at timestamptz default now(),unique(post_id,user_id));
create table if not exists follows(follow_id uuid primary key default gen_random_uuid(),follower_id uuid references users(user_id) on delete cascade not null,following_id uuid references users(user_id) on delete cascade not null,created_at timestamptz default now(),unique(follower_id,following_id),check(follower_id<>following_id));
create table if not exists files(file_id uuid primary key default gen_random_uuid(),user_id uuid references users(user_id) on delete cascade not null,object_path text not null,original_name varchar(255) not null,content_type varchar(120) not null,size_bytes bigint not null,purpose varchar(30) not null,created_at timestamptz default now());
create index if not exists idx_skills_user on skills(user_id); create index if not exists idx_goals_user on goals(user_id); create index if not exists idx_practice_user_date on practice_sessions(user_id,practiced_at desc); create index if not exists idx_posts_created on posts(created_at desc); create index if not exists idx_comments_post on comments(post_id,created_at); create index if not exists idx_likes_post on likes(post_id); create index if not exists idx_follows_follower on follows(follower_id);
